<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';$id=get_id();if(!$id)redirect_to('mahasiswa.php');$st=mysqli_prepare($koneksi,"SELECT m.*,ps.kode_program_studi,ps.nama_program_studi,f.kode_fakultas,f.nama_fakultas,u.nama_universitas FROM mahasiswa m JOIN program_studi ps ON m.id_program_studi=ps.id_program_studi JOIN fakultas f ON ps.id_fakultas=f.id_fakultas JOIN universitas u ON f.id_universitas=u.id_universitas WHERE m.id_mahasiswa=?");mysqli_stmt_bind_param($st,'i',$id);mysqli_stmt_execute($st);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($st));mysqli_stmt_close($st);if(!$r)die('Data tidak ditemukan.');if($_SESSION['kode_role']==='OPERATOR_PRODI'&&(int)$r['id_program_studi']!==(int)$_SESSION['id_program_studi']){http_response_code(403);die('403');}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail Mahasiswa</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading page-heading-flex"><div><span class="eyebrow">DATA AKADEMIK</span><h1>Detail Mahasiswa</h1><p><?=e($r['npm'])?> · <?=e($r['nama_mahasiswa'])?></p></div><a class="btn btn-outline" href="mahasiswa.php">← Kembali</a></div><div class="dashboard-panel"><div class="detail-grid"><?php $items=[['NPM',$r['npm']],['Nama',$r['nama_mahasiswa']],['Program Studi',$r['nama_program_studi']],['Fakultas',$r['nama_fakultas']],['Universitas',$r['nama_universitas']],['Jenis Kelamin',$r['jenis_kelamin']==='L'?'Laki-laki':'Perempuan'],['Tempat Lahir',$r['tempat_lahir']?:'-'],['Tanggal Lahir',$r['tanggal_lahir']?:'-'],['Tanggal Masuk',$r['tanggal_masuk']],['Status',$r['status_mahasiswa']],['Alamat',$r['alamat']?:'-']];foreach($items as [$l,$v]):?><div class="detail-item"><span><?=e($l)?></span><strong><?=e($v)?></strong></div><?php endforeach;?></div></div></main><script src="script.js"></script></body></html>